// ---------------------------------------------------------------------------
// Ed25519Tests.cs: verifies Clip Guard's ed25519 against shared vectors
// generated by the extension's library (@noble/curves) + RFC 8032.
// Build & run with tests\run-tests.bat (built-in compiler, no downloads).
// ---------------------------------------------------------------------------
using System;
using System.Diagnostics;
using System.IO;
using Aegis.ClipGuard.Crypto;

internal static class Ed25519Tests
{
    private static byte[] FromHex(string s)
    {
        byte[] b = new byte[s.Length / 2];
        for (int i = 0; i < b.Length; i++) b[i] = Convert.ToByte(s.Substring(i * 2, 2), 16);
        return b;
    }

    private static int Main(string[] args)
    {
        string path = args.Length > 0 ? args[0] : @"..\..\shared-fixtures\ed25519-vectors.txt";
        int pass = 0, fail = 0;
        Stopwatch sw = Stopwatch.StartNew();
        foreach (string raw in File.ReadAllLines(path))
        {
            string line = raw.Trim();
            if (line.Length == 0 || line.StartsWith("#")) continue;
            string[] parts = line.Split(' ');
            byte[] seed = FromHex(parts[0]);
            byte[] expected = FromHex(parts[1]);
            byte[] actual = Ed25519PublicKey.FromSeed(seed);

            byte[] secret = new byte[64];
            Array.Copy(seed, secret, 32);
            Array.Copy(expected, 0, secret, 32, 32);
            byte[] pub;
            bool detected = Ed25519PublicKey.IsSolanaSecretKey(secret, out pub);

            // Negative check: flip one bit of the public half -> must NOT be detected
            secret[40] ^= 1;
            bool falsePositive = Ed25519PublicKey.IsSolanaSecretKey(secret, out pub);

            bool same = actual.Length == expected.Length;
            for (int i = 0; same && i < 32; i++) same = actual[i] == expected[i];
            if (same && detected && !falsePositive) pass++; else fail++;
        }
        sw.Stop();
        int total = pass + fail;
        Console.WriteLine("ed25519 vectors: " + pass + "/" + total + " passed");
        Console.WriteLine("avg ms per key check: " + (total == 0 ? 0 : sw.Elapsed.TotalMilliseconds / (total * 2)).ToString("0.00"));
        return fail == 0 && total > 0 ? 0 : 1;
    }
}

